class Checker:
    def movesToStamp(self, stamp, target, result):
        if not isinstance(result, list):
            return False
        n = len(target)
        m = len(stamp)
        if len(result) > 10 * n:
            return False
        cur = ['?'] * n
        for pos in result:
            if not isinstance(pos, int) or pos < 0 or pos + m > n:
                return False
            for j, ch in enumerate(stamp):
                    cur[pos + j] = ch
        return ''.join(cur) == target

